SELECT jsonb_build_object(
'checkedAt',clock_timestamp(),'projectRef','cgjbsmqtfhqvttudyjzq',
'functions',(SELECT jsonb_agg(jsonb_build_object('signature',s.sig,'definition',pg_get_functiondef(p.oid),'checksum',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text) ORDER BY s.sig) FROM unnest(ARRAY['aka_agent_device_presence(text,text,uuid,jsonb,boolean)','aka_agent_prepare_device_change_v2(text)','aka_agent_recover_staff_credentials(text,text)','aka_agent_reset_device_binding_v2(text,text,text,uuid,jsonb,jsonb)','aka_agent_staff_client(text,text,text,jsonb)','aka_agent_staff_time_allowed(bigint)','private.aka_agent_invalidate_staff_recovery()']::text[]) s(sig) LEFT JOIN pg_proc p ON p.oid=to_regprocedure(s.sig)),
'orgStaffRls',(SELECT relrowsecurity FROM pg_class WHERE oid='public.org_staff'::regclass),
'v3Installed',to_regclass('private.aka_agent_device_collisions') IS NOT NULL,
'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.org_staff'::regclass AND a.attnum>0 AND NOT a.attisdropped),
'relations',(SELECT jsonb_agg(jsonb_build_object('name',c.oid::regclass::text,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl::text) ORDER BY c.oid::regclass::text) FROM pg_class c WHERE c.oid IN ('public.org_staff'::regclass,'public.org_organization'::regclass)),
'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.schemaname,p.tablename,p.policyname),'[]') FROM pg_policies p WHERE schemaname='public' AND tablename IN ('org_staff','org_organization')),
'staffTriggers',(SELECT jsonb_agg(pg_get_triggerdef(oid) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.org_staff'::regclass AND NOT tgisinternal),
'otherFunctions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'checksum',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND p.prokind='f' AND p.proname LIKE 'aka_agent_%'),
'collisions',(SELECT jsonb_build_object('groups',count(*),'staff',coalesce(sum(n),0),'largest',coalesce(max(n),0)) FROM (SELECT count(*) n FROM public.org_staff WHERE aka_agent_device_fingerprint_hash IS NOT NULL GROUP BY aka_agent_device_fingerprint_hash HAVING count(*)>1) d),
'migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version DESC) FROM (SELECT version,name FROM supabase_migrations.schema_migrations ORDER BY version DESC LIMIT 10)m)
) AS snapshot;
